863	std::vector<std::pair<std::vector<std::string>, Node>>
864	LiaStarUtils::getMatrices(Node variables, Node n)
865	{
866	  // Render a DNF predicate into one Normaliz matrix per disjunct (cone). A
867	  // disjunction yields one matrix per child; any other shape (atom,
868	  // conjunction, boolean constant) is a single disjunct handled by `getMatrix`.
869	  Assert(n.getType().isBoolean()) << "n: " << n << std::endl;
870	  if (n.getKind() == Kind::OR)
871	  {
872	    std::vector<std::pair<std::vector<std::string>, Node>> pairs;
873	    for (size_t i = 0; i < n.getNumChildren(); i++)
874	    {
875	      Trace("liastar-ext") << "Disjunction " << i << ": " << n[i] << std::endl;
876	      pairs.push_back(getMatrix(variables, n[i]));
877	    }
878	    return pairs;
879	  }
880	  return {getMatrix(variables, n)};
881	}
