123	Node LiaStarUtils::removeItesAndNots(Node n, Env* e)
124	{
125	  // Eliminate if-then-elses, then push negations to the leaves (and rewrite
126	  // negated comparisons into positive ones). The result is a negation-free,
127	  // ite-free formula over positive linear (in)equalities.
128	  Node noItes = removeItes(n, e);
129	  Trace("liastar-ext-debug") << "noItes: " << noItes << std::endl;
130	  Node nnf = removeNot(noItes, e);
131	  Trace("liastar-ext-debug") << "nnf: " << nnf << std::endl;
132	  // emit queries validating both transformations on the liastar-ext-smt trace
133	  traceDistinctQuery("noItes", n, noItes);
134	  traceDistinctQuery("nnf", noItes, nnf);
135	  return nnf;
136	}
