138	Node LiaStarUtils::toDNF(Node n, Env* e)
139	{
140	  // Normalize (no ites/negations) and then distribute AND over OR to reach
141	  // disjunctive normal form. `recursiveFlatten` collapses nested AND/OR so each
142	  // disjunct is a flat conjunction (a single cone).
143	  Node nnf = removeItesAndNots(n, e);
144	  Node dnf = distribute(nnf, e);
145	  Trace("liastar-ext-debug") << "dnf: " << dnf << std::endl;
146	  dnf = recursiveFlatten(e->getNodeManager(), dnf);
147	  // emit a query validating the distribution on the liastar-ext-smt trace
148	  traceDistinctQuery("dnf", nnf, dnf);
149	  return dnf;
150	}
