152	Node LiaStarUtils::recursiveFlatten(NodeManager* nm, Node n)
153	{
154	  // Collapse nested associative operators, e.g. (or a (or b c)) -> (or a b c)
155	  // and likewise for the conjuncts one level down, so a DNF is exactly two
156	  // levels deep: a flat OR of flat ANDs.
157	  Trace("liastar-ext-dnf") << "recursiveFlatten::n: " << n << std::endl;
158	  if (n.getNumChildren() == 0)
159	  {
160	    return n;
161	  }
162	  Node flat = expr::algorithm::flatten(nm, n);
163	  std::vector<Node> children;
164	  for (const auto& child : flat)
165	  {
166	    children.push_back(expr::algorithm::flatten(nm, child));
167	  }
168	  return nm->mkNode(flat.getKind(), children);
169	}

403	Node LiaStarUtils::removeNot(Node n, Env* e)
404	{
405	  // Convert to negation normal form and then drive every remaining negation
406	  // into the comparison it negates, so the formula has no NOT nodes and no
407	  // disequalities (which are not convex and so cannot be a single cone).
408	  NodeManager* nm = e->getNodeManager();
409	  Node nnf = booleans::TheoryBoolRewriter::computeNnfNorm(nm, n);
410	  Kind k = nnf.getKind();
411	  switch (k)
412	  {
413	    case Kind::VARIABLE:
414	    case Kind::BOUND_VARIABLE:
415	    case Kind::CONST_BOOLEAN:
416	    case Kind::LT:
417	    case Kind::GT:
418	    case Kind::LEQ:
419	    case Kind::GEQ:
420	    case Kind::EQUAL: return nnf;
421	    case Kind::AND:
422	    {
423	      std::vector<Node> conjuncts;
424	      for (Node child : nnf)
425	      {
426	        conjuncts.push_back(removeNot(child, e));
427	      }
428	      return nm->mkNode(Kind::AND, conjuncts);
429	    }
430	    case Kind::OR:
431	    {
432	      std::vector<Node> disjuncts;
433	      for (Node child : nnf)
434	      {
435	        disjuncts.push_back(removeNot(child, e));
436	      }
437	      return nm->mkNode(Kind::OR, disjuncts);
438	    }
439	    case Kind::NOT:
440	    {
441	      // computeNnfNorm leaves a NOT only directly above an atom; rewrite the
442	      // negated comparison into the equivalent positive one.
443	      Kind kind = nnf[0].getKind();
444	      switch (kind)
445	      {
446	        case Kind::LT:
447	        {
448	          //(not (< a b)) is rewritten as (>= a b)
449	          return nm->mkNode(Kind::GEQ, nnf[0][0], nnf[0][1]);
450	        }
451	        case Kind::GT:
452	        {
453	          //(not (> a b)) is rewritten as (<= a b)
454	          return nm->mkNode(Kind::LEQ, nnf[0][0], nnf[0][1]);
455	        }
456	        case Kind::LEQ:
457	        {
458	          //(not (<= a b)) is rewritten as (> a b)
459	          return nm->mkNode(Kind::GT, nnf[0][0], nnf[0][1]);
460	        }
461	        case Kind::GEQ:
462	        {
463	          //(not (>= a b)) is rewritten as (< a b)
464	          return nm->mkNode(Kind::LT, nnf[0][0], nnf[0][1]);
465	        }
466	        case Kind::EQUAL:
467	        {
468	          // (not (= a b)) is the union of two half-spaces, so it is rewritten
469	          // as the disjunction (or (> a b) (< a b)).
470	          Node a = nnf[0][0];
471	          Node b = nnf[0][1];
472	          Node gt = nm->mkNode(Kind::GT, a, b);
473	          Node lt = nm->mkNode(Kind::LT, a, b);
474	          return gt.orNode(lt);
475	        }
476	        default:
477	          InternalError() << "Unexpected negated kind. Node " << n
478	                          << " has kind: " << n.getKind() << std::endl;
479	      }
480	      break;
481	    }
482	    default:
483	    {
484	      break;
485	    }
486	  }
487	  InternalError() << "Unexpected kind. Node " << n
488	                  << " has kind: " << n.getKind() << std::endl;
489	}
